<script setup lang="ts">
import {computed,ref} from 'vue';
export interface VGridColumn {key:string;label:string;sortable?:boolean;hidden?:boolean}
const props=withDefaults(defineProps<{rows:Record<string,unknown>[];columns:VGridColumn[];rowKey?:string;pageSize?:number;selectable?:boolean;searchable?:boolean}>(),{rowKey:'id',pageSize:25,selectable:true,searchable:true});
const emit=defineEmits<{selectionChange:[ids:string[]];bulkAction:[ids:string[]]}>();
const search=ref(''),sort=ref(''),descending=ref(false),page=ref(1),selected=ref<string[]>([]),visible=ref<string[]>([]);
const orderedColumns=computed(()=>props.columns.filter(c=>!c.hidden && !visible.value.includes(c.key)));
const filtered=computed(()=>{const q=search.value.toLowerCase();const data=props.rows.filter(r=>!q||Object.values(r).some(v=>String(v??'').toLowerCase().includes(q))); if(sort.value)data.sort((a,b)=>String(a[sort.value]??'').localeCompare(String(b[sort.value]??''),undefined,{numeric:true})*(descending.value?-1:1));return data;});
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/Math.max(1,props.pageSize))));
const rows=computed(()=>filtered.value.slice((Math.min(page.value,pages.value)-1)*props.pageSize,Math.min(page.value,pages.value)*props.pageSize));
const key=(row:Record<string,unknown>)=>String(row[props.rowKey]);
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(v=>v!==id):[...selected.value,id];emit('selectionChange',selected.value)}
function toggleSort(column:VGridColumn){if(!column.sortable)return;descending.value=sort.value===column.key?!descending.value:false;sort.value=column.key;}
function toggleColumn(k:string){visible.value=visible.value.includes(k)?visible.value.filter(x=>x!==k):[...visible.value,k]}
</script>
<template><div class="vx-advanced-grid"><div class="vx-advanced-grid__tools"><input v-if="searchable" v-model="search" type="search" placeholder="Search records" aria-label="Search records" @input="page=1"/><details><summary>Columns</summary><label v-for="c in columns" :key="c.key"><input type="checkbox" :checked="!visible.includes(c.key) && !c.hidden" :disabled="c.hidden" @change="toggleColumn(c.key)"/>{{c.label}}</label></details><button v-if="selected.length" type="button" @click="emit('bulkAction',selected)">Actions ({{selected.length}})</button><slot name="toolbar" :selection="selected"/></div><div class="vx-advanced-grid__scroll"><table><thead><tr><th v-if="selectable" scope="col">Select</th><th v-for="c in orderedColumns" :key="c.key" scope="col"><button v-if="c.sortable" type="button" @click="toggleSort(c)">{{c.label}} {{sort===c.key?(descending?'↓':'↑'):'↕'}}</button><span v-else>{{c.label}}</span></th></tr></thead><tbody><tr v-for="row in rows" :key="key(row)"><td v-if="selectable"><input type="checkbox" :checked="selected.includes(key(row))" :aria-label="'Select '+key(row)" @change="toggle(key(row))"/></td><td v-for="c in orderedColumns" :key="c.key"><slot :name="'cell-'+c.key" :row="row" :value="row[c.key]">{{row[c.key]}}</slot></td></tr><tr v-if="!rows.length"><td :colspan="orderedColumns.length+(selectable?1:0)"><slot name="empty">No matching records</slot></td></tr></tbody></table></div><footer class="vx-advanced-grid__footer"><small>{{filtered.length}} records · Page {{Math.min(page,pages)}} of {{pages}}</small><button type="button" :disabled="page<=1" @click="page--">Previous</button><button type="button" :disabled="page>=pages" @click="page++">Next</button></footer></div></template>
